// Module-level in-memory cache for FleetDesk data
let fleetDataCache: {
  stats?: VehicleDashboardStats;
  vehicles?: VehicleRecord[];
  drivers?: DriverRecord[];
  trips?: TripRecord[];
  maintenance?: MaintenanceRecord[];
  vendors?: InsuranceVendorRecord[];
  parts?: PartAccessoryRecord[];
  timestamp: number;
} | null = null;

/**
 * Calculates next document version and cleans candidate title
 */
function computeNextDocVersion(
  candidateTitle: string,
  existingDocs: any[],
  docType: string
): { currentVersion: string; nextVersion: string; baseTitle: string } {
  const versionRegex = /\(v?(\d+(?:\.\d+)?)\)/i;
  let baseTitle = candidateTitle.replace(/\s*\(v?\d+(?:\.\d+)?\)\s*$/i, "").trim();
  if (!baseTitle) {
    const typeLabel = VEHICLE_DOC_TYPES.find((t) => t.value === docType)?.label || docType;
    baseTitle = `${typeLabel} Document`;
  }

  let maxMajor = 1;
  let maxMinor = 0;
  let foundAnyVersion = false;

  (existingDocs || []).forEach((d) => {
    const title = d.title || "";
    const match = title.match(versionRegex);
    if (match) {
      foundAnyVersion = true;
      const numStr = match[1].replace(/^v/i, "");
      const parts = numStr.split(".").map((n: string) => parseInt(n, 10) || 0);
      const major = parts[0] || 1;
      const minor = parts[1] || 0;
      if (major > maxMajor || (major === maxMajor && minor > maxMinor)) {
        maxMajor = major;
        maxMinor = minor;
      }
    }
  });

  const currentVersion = foundAnyVersion ? `v${maxMajor}.${maxMinor}` : "v1.0";
  const nextVersion = `v${maxMajor + 1}.0`;

  return { currentVersion, nextVersion, baseTitle };
}

/**
 * Extracts version tag like "v2.0" from title if present
 */
function extractVersionFromTitle(title: string): string | null {
  const match = (title || "").match(/\((v?\d+(?:\.\d+)?)\)/i);
  if (!match) return null;
  const v = match[1];
  return v.toLowerCase().startsWith("v") ? v : `v${v}`;
}


// ============================================================================
// FAULT-TOLERANT MODULE & TAB ERROR BOUNDARY
// ============================================================================

interface FleetErrorBoundaryProps {
  children: React.ReactNode;
  tabName?: string;
  onReset?: () => void;
}

interface FleetErrorBoundaryState {
  hasError: boolean;
  error: Error | null;
}

export class FleetErrorBoundary extends React.Component<FleetErrorBoundaryProps, FleetErrorBoundaryState> {
  constructor(props: FleetErrorBoundaryProps) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error: Error): FleetErrorBoundaryState {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {
    console.error(`[FleetErrorBoundary] Caught error in ${this.props.tabName || "FleetDesk"}:`, error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="p-8 rounded-2xl border border-danger/30 bg-danger/5 text-center space-y-4 my-6 shadow-sm">
          <div className="w-10 h-10 rounded-xl bg-danger/10 text-danger flex items-center justify-center mx-auto">
            <AlertTriangle className="w-5 h-5" />
          </div>
          <div>
            <h3 className="text-sm font-bold text-foreground">
              {this.props.tabName ? `${this.props.tabName} View Temporarily Unavailable` : "Module Section Error"}
            </h3>
            <p className="text-xs text-muted-foreground mt-1 max-w-md mx-auto">
              {this.state.error?.message || "An unexpected error occurred while rendering this tab."}
            </p>
          </div>
          <div className="flex items-center justify-center gap-2 pt-2">
            <AppButton
              variant="outline"
              size="sm"
              onClick={() => {
                this.setState({ hasError: false, error: null });
                if (this.props.onReset) this.props.onReset();
              }}
              className="text-xs h-8 px-3"
            >
              Retry Tab
            </AppButton>
          </div>
        </div>
      );
    }
    return this.props.children;
  }
}

