  // Automatically sync verified RTO office into form whenever plate is recognized
  useEffect(() => {
    if (newPlateInfo.rtoName) {
      setNewVehicleRtoOffice(newPlateInfo.rtoName);
    }
  }, [newPlateInfo.rtoName]);

  // Instant Auto-Fetch Hook: triggers automatically whenever user types 6+ plate characters
  useEffect(() => {
    const clean = newVehiclePlate.replace(/[^a-zA-Z0-9]/g, "").toUpperCase();
    if (clean.length >= 6 && activeTab === "register") {
      const timer = setTimeout(() => {
        handlePortalAutoFetch(clean);
      }, 450);
      return () => clearTimeout(timer);
    }
  }, [newVehiclePlate, activeTab]);

  // Auto-fetch documents, historical insurance policies, and PUC certificates for viewingVehicle dossier
  useEffect(() => {
    if (viewingVehicle?.id) {
      const vId = viewingVehicle.id;
      // 1. Fetch vault documents
      fetchVehicleDocumentsAction(vId).then((res) => {
        if (res.success && res.documents && res.documents.length > 0) {
          setViewingVehicle((prev) => (prev && prev.id === vId ? { ...prev, documents: res.documents } : prev));
          setVehicles((prev) =>
            prev.map((v) => (v.id === vId ? { ...v, documents: res.documents } : v))
          );
        }
      }).catch((err) => console.error("Error fetching vehicle documents:", err));
      // 2. Fetch insurance policies (renewals & history)
      fetchVehicleInsurancePoliciesAction(vId).then((res) => {
        if (res.success && res.policies) {
          setViewingVehiclePolicies(res.policies);
        }
      }).catch((err) => console.error("Error fetching vehicle policies:", err));
      // 3. Fetch PUC certificates (renewals & history)
      fetchVehiclePucCertificatesAction(vId).then((res) => {
        if (res.success && res.certificates) {
          setViewingVehiclePucs(res.certificates);
        }
      }).catch((err) => console.error("Error fetching vehicle PUCs:", err));
    } else {
      setViewingVehiclePolicies([]);
      setViewingVehiclePucs([]);
    }
  }, [viewingVehicle?.id]);

  /**
   * Universal 360-Degree Vehicle Document Aggregator
   * Unifies direct vault uploads, master compliance documents (RC, Insurance, PUC, Fitness, Permit, Tax, Invoices),
   * workshop maintenance invoices & job card attachments, spare parts warranty cards & purchase bills,
   * transit trip sheets, toll receipts, fuel slips, chauffeur licenses, and renewed policies history.
   */
  const computeVehicleAggregatedDocs = useCallback((
    veh: VehicleRecord,
    allMaintenance: MaintenanceRecord[],
    allParts: PartAccessoryRecord[],
    allTrips: TripRecord[],
    allDrivers: DriverRecord[],
    additionalPolicies: VehicleInsurancePolicyRecord[] = [],
    additionalPucs: VehiclePucCertificateRecord[] = []
  ): AggregatedVehicleDoc[] => {
    const norm = (s?: string | null) => (s || "").replace(/[^a-zA-Z0-9]/g, "").toUpperCase();
    const targetId = veh.id;
    const targetPlate = norm(veh.registration_number);

    const vServices = allMaintenance.filter(
      (m) => (m.vehicle_id && m.vehicle_id === targetId) || (m.vehicle_reg && norm(m.vehicle_reg) === targetPlate)
    ).sort((a, b) => new Date(b.service_date).getTime() - new Date(a.service_date).getTime());

    const vParts = allParts.filter(
      (p) => (p.vehicle_id && p.vehicle_id === targetId) || (p.assigned_vehicle_reg && norm(p.assigned_vehicle_reg) === targetPlate)
    );

    const vTrips = allTrips.filter(
      (t) => (t.vehicle_id && t.vehicle_id === targetId) || (t.vehicle_reg && norm(t.vehicle_reg) === targetPlate)
    ).sort((a, b) => new Date(b.plan_date || b.created_at || "").getTime() - new Date(a.plan_date || a.created_at || "").getTime());

    const assignedDriver: any = allDrivers.find((d: any) => d.id === veh.assigned_driver_id || (veh.assignedDriver && d.id === veh.assignedDriver.id)) || veh.assignedDriver;

    const docs: AggregatedVehicleDoc[] = [];
    const existingKeys = new Set<string>();

    // 1. Direct Vault Documents (Top priority: Actual uploaded scanned files)
    const vaultDocTypes = new Set<string>();
    const vaultDocTitles = new Set<string>();
    const vaultDocNumbers = new Set<string>();

    const pushDoc = (doc: AggregatedVehicleDoc) => {
      const cleanTitle = (doc.title || "").replace(/\s*\(v?\d+(?:\.\d+)?\)\s*$/i, "").trim().toLowerCase();
      const docNum = (doc.document_number || "").trim().toLowerCase();

      // If pushing a synthetic / master digital record (no file_url), do not push if vault already has this doc
      if (!doc.file_url) {
        if (vaultDocTitles.has(cleanTitle)) return;
        if (docNum && vaultDocNumbers.has(docNum)) return;
      }

      const key = doc.file_url ? `url:${doc.file_url}` : `type:${doc.doc_type}:${doc.document_number || doc.title}`;
      if (existingKeys.has(key)) return;
      existingKeys.add(key);
      docs.push(doc);
    };

    (veh.documents || []).forEach((d) => {
      if (d.doc_type) vaultDocTypes.add(d.doc_type.toUpperCase());
      const cleanT = (d.title || "").replace(/\s*\(v?\d+(?:\.\d+)?\)\s*$/i, "").trim().toLowerCase();
      if (cleanT) vaultDocTitles.add(cleanT);
      if (d.document_number) vaultDocNumbers.add(d.document_number.trim().toLowerCase());

      // Smart semantic detection of doc type from title/doc_number to reconcile mismatched category tags
      const lowerTitle = (d.title || "").toLowerCase();
      const lowerDocNum = (d.document_number || "").toLowerCase();
      const normVin = (veh.vin_chassis_number || "").toLowerCase();
      const normReg = (veh.registration_number || "").toLowerCase();

      if (
        lowerTitle.includes("rc smart card") ||
        lowerTitle.includes("rc card") ||
        lowerTitle.includes("registration certificate") ||
        (normVin && lowerDocNum === normVin) ||
        (normReg && lowerDocNum === normReg)
      ) {
        vaultDocTypes.add("RC");
      }
      if (
        lowerTitle.includes("insurance") ||
        lowerTitle.includes("policy") ||
        (veh.insurance_policy_number && lowerDocNum === veh.insurance_policy_number.toLowerCase())
      ) {
        vaultDocTypes.add("INSURANCE");
      }
      if (
        lowerTitle.includes("puc") ||
        lowerTitle.includes("pollution") ||
        (veh.puc_certificate_number && lowerDocNum === veh.puc_certificate_number.toLowerCase())
      ) {
        vaultDocTypes.add("PUC");
      }
      if (
        lowerTitle.includes("fitness") ||
        ((veh as any).fitness_certificate_number && lowerDocNum === ((veh as any).fitness_certificate_number || "").toLowerCase())
      ) {
        vaultDocTypes.add("FITNESS");
      }

      pushDoc({
        id: d.id,
        doc_type: d.doc_type || "OTHER",
        categoryLabel: VEHICLE_DOC_TYPES.find((t) => t.value === d.doc_type)?.label || d.doc_type || "Vault Document",
        title: d.title || d.file_name || "Vehicle Document",
        file_name: d.file_name || "document.pdf",
        file_size: d.file_size || null,
        file_type: d.file_type || resolveMimeFromName(d.file_name || ""),
        file_url: d.file_url,
        uploaded_at: d.uploaded_at || veh.created_at,
        expiry_date: d.expiry_date || null,
        document_number: d.document_number || null,
        status: d.status || "VALID",
        sourceModule: "VAULT",
        sourceLabel: "Vehicle Document Vault",
        isDirectVaultDoc: true
      });
    });

    // 2. RC Smart Card & Vehicle Identity (Only synthesize if no vault RC doc exists)
    const rcUrl = (veh as any).rc_doc_url || (veh as any).rc_document_url || null;
    if (!vaultDocTypes.has("RC")) {
      pushDoc({
        id: `master-doc-rc-${targetId}`,
        doc_type: "RC",
        categoryLabel: "RC Smart Card",
        title: `RC Smart Card (${veh.registration_number})`,
        file_name: rcUrl ? `RC_${targetPlate}.pdf` : `RC_${targetPlate}.pdf`,
        file_size: rcUrl ? "Official Certificate" : null,
        file_type: "application/pdf",
        file_url: rcUrl,
        uploaded_at: veh.registration_date || veh.created_at,
        expiry_date: null,
        document_number: veh.vin_chassis_number || veh.registration_number,
        status: "VALID",
        sourceModule: "MASTER",
        sourceLabel: `RTO Transport Registry (${veh.rto_office || "State RTO"})`,
        isDirectVaultDoc: false
      });
    }

    // 3. Insurance Policies (Master + Historical Policies)
    const insUrl = (veh as any).insurance_doc_url || (veh as any).policy_document_url || null;
    if (!vaultDocTypes.has("INSURANCE") && (veh.insurance_policy_number || insUrl || veh.insurance_expiry_date)) {
      pushDoc({
        id: `master-doc-ins-${targetId}`,
        doc_type: "INSURANCE",
        categoryLabel: "Motor Insurance Policy",
        title: `Insurance Policy: ${veh.insurance_vendor || "Comprehensive"} (${veh.insurance_policy_number || targetPlate})`,
        file_name: insUrl ? `Insurance_${targetPlate}.pdf` : `Insurance_${targetPlate}.pdf`,
        file_size: insUrl ? "Policy Document" : null,
        file_type: "application/pdf",
        file_url: insUrl,
        uploaded_at: veh.registration_date || veh.created_at,
        expiry_date: veh.insurance_expiry_date || null,
        document_number: veh.insurance_policy_number || null,
        status: "VALID",
        sourceModule: "INSURANCE",
        sourceLabel: `Insurance Policy (${veh.insurance_vendor || "Authorized Provider"})`,
        isDirectVaultDoc: false
      });
    }

    additionalPolicies.forEach((pol) => {
      const polDocUrl = pol.policy_document_url || (pol as any).document_url || null;
      if (polDocUrl || !vaultDocTypes.has("INSURANCE")) {
        pushDoc({
          id: `ins-pol-${pol.id}`,
          doc_type: "INSURANCE",
          categoryLabel: "Insurance Renewal Policy & Bill",
          title: `Insurance Renewal: ${pol.insurer_name} (₹${(Number(pol.premium_amount) || 0).toLocaleString()} Premium)`,
          file_name: `Insurance_Policy_${pol.policy_number}.pdf`,
          file_size: polDocUrl ? "Renewal Bill" : null,
          file_type: "application/pdf",
          file_url: polDocUrl,
          uploaded_at: pol.start_date || pol.created_at,
          expiry_date: pol.end_date || null,
          document_number: pol.policy_number || null,
          status: pol.is_active ? "VALID" : "EXPIRED",
          sourceModule: "INSURANCE",
          sourceLabel: `Policy Term (${pol.start_date} → ${pol.end_date})`,
          isDirectVaultDoc: false
        });
      }
    });

    // 4. PUC Emission Certificates (Master + Historical Certificates)
    const pucUrl = (veh as any).puc_doc_url || (veh as any).certificate_doc_url || null;
    if (!vaultDocTypes.has("PUC") && (veh.puc_certificate_number || pucUrl || veh.puc_expiry_date)) {
      pushDoc({
        id: `master-doc-puc-${targetId}`,
        doc_type: "PUC",
        categoryLabel: "PUC Certificate",
        title: `PUC Certificate (${veh.puc_certificate_number || targetPlate})`,
        file_name: `PUC_${targetPlate}.pdf`,
        file_size: pucUrl ? "Emission Certificate" : null,
        file_type: "application/pdf",
        file_url: pucUrl,
        uploaded_at: veh.registration_date || veh.created_at,
        expiry_date: veh.puc_expiry_date || null,
        document_number: veh.puc_certificate_number || null,
        status: "VALID",
        sourceModule: "PUC",
        sourceLabel: `Emission Clearance (${veh.puc_expiry_date ? "Valid upto " + veh.puc_expiry_date : "RTO Approved"})`,
        isDirectVaultDoc: false
      });
    }

    additionalPucs.forEach((puc) => {
      const pucDocUrl = puc.document_url || null;
      if (pucDocUrl) {
        pushDoc({
          id: `puc-test-${puc.id}`,
          doc_type: "PUC",
          categoryLabel: "PUC Renewal & Test Bill",
          title: `PUC Certificate: ${puc.certificate_number} (${puc.testing_center_name || "Emission Center"})`,
          file_name: `PUC_Certificate_${puc.certificate_number}.pdf`,
          file_size: "Emission Slip",
          file_type: "application/pdf",
          file_url: pucDocUrl,
          uploaded_at: puc.valid_from || puc.created_at,
          expiry_date: puc.valid_upto || null,
          document_number: puc.certificate_number || null,
          status: puc.is_active ? "VALID" : "EXPIRED",
          sourceModule: "PUC",
          sourceLabel: `Test Center (${puc.testing_center_name || "Authorized"} • ${puc.emission_norm || "BS-VI"})`,
          isDirectVaultDoc: false
        });
      }
    });

    // 5. Workshop Services & Maintenance Bills (Only include if invoice or file exists)
    vServices.forEach((m: any) => {
      const sCenter = m.service_center || "Authorized Workshop";
      const sDate = m.service_date ? new Date(m.service_date).toLocaleDateString("en-IN", { month: "short", day: "numeric", year: "numeric" }) : "";
      const jobNum = m.job_card_number || `JOB-${m.id.slice(0, 8).toUpperCase()}`;

      if (m.invoice_url) {
        pushDoc({
          id: `svc-job-${m.id}`,
          doc_type: "MAINTENANCE",
          categoryLabel: "Workshop Service Bill",
          title: `Service Bill: ${m.service_type || "Periodic Inspection"} (${sCenter} • ₹${(Number(m.cost) || 0).toLocaleString()})`,
          file_name: `Service_Bill_${jobNum}.pdf`,
          file_size: `₹${(Number(m.cost) || 0).toLocaleString()}`,
          file_type: "application/pdf",
          file_url: m.invoice_url,
          uploaded_at: m.service_date || m.created_at,
          expiry_date: null,
          document_number: jobNum,
          status: "VALID",
          sourceModule: "SERVICE",
          sourceLabel: `Service Event (${sCenter} • ${sDate})`,
          isDirectVaultDoc: false
        });
      }

      if (m.attachments && Array.isArray(m.attachments)) {
        m.attachments.forEach((att: any, attIdx: number) => {
          if (att.file_url) {
            pushDoc({
              id: `svc-att-${m.id}-${att.id || attIdx}`,
              doc_type: "MAINTENANCE",
              categoryLabel: "Job Card Attachment",
              title: `${att.file_name || "Job Card Scan"} - ${sCenter}`,
              file_name: att.file_name || "service_document.pdf",
              file_size: att.file_size || null,
              file_type: att.file_type || resolveMimeFromName(att.file_name || ""),
              file_url: att.file_url,
              uploaded_at: att.uploaded_at || m.service_date,
              expiry_date: null,
              document_number: jobNum,
              status: "VALID",
              sourceModule: "SERVICE",
              sourceLabel: `Attachment (${sCenter} • ${sDate})`,
              isDirectVaultDoc: false
            });
          }
        });
      }
    });

    // 6. Installed Spare Parts Warranties & Bills (Only include if doc exists)
    vParts.forEach((p: any) => {
      const pNum = p.part_number || `PART-${p.id.slice(0, 6).toUpperCase()}`;
      const pDocUrl = p.warranty_policy_doc_url || p.invoice_url || p.document_url || null;

      if (pDocUrl) {
        pushDoc({
          id: `part-doc-${p.id}`,
          doc_type: "PART",
          categoryLabel: "Part Warranty & Bill",
          title: `Part Warranty & Bill: ${p.name} (${pNum})`,
          file_name: `Part_Warranty_${pNum}.pdf`,
          file_size: `₹${(Number(p.purchase_amount) || 0).toLocaleString()}`,
          file_type: "application/pdf",
          file_url: pDocUrl,
          uploaded_at: p.created_at,
          expiry_date: p.warranty_expiry_date || null,
          document_number: pNum,
          status: "VALID",
          sourceModule: "PART",
          sourceLabel: `Mounted Part (${p.name} • ₹${(Number(p.purchase_amount) || 0).toLocaleString()})`,
          isDirectVaultDoc: false
        });
      }
    });

    // 7. Trips Sheets, Toll Slips & Fuel Bills (Only include if file exists)
    vTrips.forEach((t: any) => {
      const routeStr = `${t.origin} → ${t.destination}`;
      const tripNum = `TRIP-${t.id.slice(0, 8).toUpperCase()}`;

      if (t.trip_sheet_url) {
        pushDoc({
          id: `trip-sheet-${t.id}`,
          doc_type: "TRIP",
          categoryLabel: "Trip Sheet Voucher",
          title: `Trip Movement Sheet: ${t.traveler_name || "Corporate"} (${routeStr})`,
          file_name: `Trip_Sheet_${tripNum}.pdf`,
          file_size: "Movement Voucher",
          file_type: "application/pdf",
          file_url: t.trip_sheet_url,
          uploaded_at: t.plan_date || t.created_at,
          expiry_date: null,
          document_number: tripNum,
          status: "VALID",
          sourceModule: "TRIP",
          sourceLabel: `Transit Route (${routeStr})`,
          isDirectVaultDoc: false
        });
      }

      if (t.toll_receipt_url) {
        pushDoc({
          id: `trip-toll-${t.id}`,
          doc_type: "TRIP",
          categoryLabel: "Toll / Fastag Slip",
          title: `Toll Receipt: ${t.traveler_name || "Chauffeur"} (${routeStr})`,
          file_name: `Toll_Slip_${tripNum}.pdf`,
          file_size: "Receipt Slip",
          file_type: "application/pdf",
          file_url: t.toll_receipt_url,
          uploaded_at: t.plan_date || t.created_at,
          expiry_date: null,
          document_number: tripNum,
          status: "VALID",
          sourceModule: "TRIP",
          sourceLabel: `Toll Expense (${routeStr})`,
          isDirectVaultDoc: false
        });
      }

      if (t.fuel_receipt_url) {
        pushDoc({
          id: `trip-fuel-${t.id}`,
          doc_type: "TRIP",
          categoryLabel: "Fuel Pump Slip",
          title: `Fuel Card / Pump Bill: ${t.traveler_name || targetPlate}`,
          file_name: `Fuel_Bill_${tripNum}.pdf`,
          file_size: "Fuel Slip",
          file_type: "application/pdf",
          file_url: t.fuel_receipt_url,
          uploaded_at: t.plan_date || t.created_at,
          expiry_date: null,
          document_number: tripNum,
          status: "VALID",
          sourceModule: "TRIP",
          sourceLabel: `Fuel Expense (${routeStr})`,
          isDirectVaultDoc: false
        });
      }
    });

    // 8. Chauffeur ID & License (Only include if file exists)
    if (assignedDriver && (assignedDriver.license_doc_url || assignedDriver.identity_doc_url)) {
      if (assignedDriver.license_doc_url) {
        pushDoc({
          id: `drv-lic-${assignedDriver.id}`,
          doc_type: "DRIVER",
          categoryLabel: "Chauffeur Driving License",
          title: `Driving License: ${assignedDriver.full_name} (${assignedDriver.license_number || "Driver"})`,
          file_name: `License_${(assignedDriver.full_name || "driver").replace(/\s+/g, "_")}.pdf`,
          file_size: "License Document",
          file_type: "application/pdf",
          file_url: assignedDriver.license_doc_url,
          uploaded_at: assignedDriver.created_at,
          expiry_date: assignedDriver.license_expiry_date || null,
          document_number: assignedDriver.license_number || null,
          status: "VALID",
          sourceModule: "DRIVER",
          sourceLabel: `Assigned Chauffeur (${assignedDriver.full_name})`,
          isDirectVaultDoc: false
        });
      }

      if (assignedDriver.identity_doc_url) {
        pushDoc({
          id: `drv-id-${assignedDriver.id}`,
          doc_type: "DRIVER",
          categoryLabel: "Chauffeur Identity Proof",
          title: `Chauffeur Identity Card: ${assignedDriver.full_name}`,
          file_name: `Identity_${(assignedDriver.full_name || "driver").replace(/\s+/g, "_")}.pdf`,
          file_size: "Identity Proof",
          file_type: "application/pdf",
          file_url: assignedDriver.identity_doc_url,
          uploaded_at: assignedDriver.created_at,
          expiry_date: null,
          document_number: null,
          status: "VALID",
          sourceModule: "DRIVER",
          sourceLabel: `Identity Verification (${assignedDriver.full_name})`,
          isDirectVaultDoc: false
        });
      }
    }

    // 9. Fitness, Commercial Permit, Road Tax, Purchase Invoice
    if (!vaultDocTypes.has("FITNESS") && (veh.fitness_expiry_date || (veh as any).fitness_doc_url)) {
      pushDoc({
        id: `master-doc-fitness-${targetId}`,
        doc_type: "FITNESS",
        categoryLabel: "Fitness Certificate",
        title: `Transport Fitness Certificate (${targetPlate})`,
        file_name: `Fitness_${targetPlate}.pdf`,
        file_size: (veh as any).fitness_doc_url ? "Fitness Certificate" : null,
        file_type: "application/pdf",
        file_url: (veh as any).fitness_doc_url || null,
        uploaded_at: veh.registration_date || veh.created_at,
        expiry_date: veh.fitness_expiry_date || null,
        document_number: null,
        status: "VALID",
        sourceModule: "MASTER",
        sourceLabel: `Commercial Transport Fitness`,
        isDirectVaultDoc: false
      });
    }

    if (!vaultDocTypes.has("PERMIT") && (veh as any).permit_doc_url) {
      pushDoc({
        id: `master-doc-permit-${targetId}`,
        doc_type: "PERMIT",
        categoryLabel: "Commercial Permit",
        title: `Commercial Tourist Permit (${targetPlate})`,
        file_name: `Permit_${targetPlate}.pdf`,
        file_size: "Tourist Permit",
        file_type: "application/pdf",
        file_url: (veh as any).permit_doc_url,
        uploaded_at: veh.registration_date || veh.created_at,
        expiry_date: null,
        document_number: null,
        status: "VALID",
        sourceModule: "MASTER",
        sourceLabel: `Commercial RTO Permit`,
        isDirectVaultDoc: false
      });
    }

    if (!vaultDocTypes.has("ROAD_TAX") && (veh as any).road_tax_doc_url) {
      pushDoc({
        id: `master-doc-roadtax-${targetId}`,
        doc_type: "ROAD_TAX",
        categoryLabel: "Road Tax Receipt",
        title: `Motor Vehicle Road Tax Payment Receipt (${targetPlate})`,
        file_name: `Road_Tax_${targetPlate}.pdf`,
        file_size: "Tax Receipt",
        file_type: "application/pdf",
        file_url: (veh as any).road_tax_doc_url,
        uploaded_at: veh.registration_date || veh.created_at,
        expiry_date: null,
        document_number: null,
        status: "VALID",
        sourceModule: "MASTER",
        sourceLabel: `State Motor Vehicle Tax`,
        isDirectVaultDoc: false
      });
    }

    if (!vaultDocTypes.has("INVOICE") && ((veh as any).invoice_doc_url || veh.purchase_cost || veh.purchase_price)) {
      pushDoc({
        id: `master-doc-invoice-${targetId}`,
        doc_type: "INVOICE",
        categoryLabel: "Purchase Invoice & Challan",
        title: `Purchase Invoice & Delivery Challan (${targetPlate})`,
        file_name: `Invoice_${targetPlate}.pdf`,
        file_size: `₹${(Number(veh.purchase_cost || veh.purchase_price || 0)).toLocaleString()}`,
        file_type: "application/pdf",
        file_url: (veh as any).invoice_doc_url || null,
        uploaded_at: veh.registration_date || veh.created_at,
        expiry_date: null,
        document_number: veh.vin_chassis_number || null,
        status: "VALID",
        sourceModule: "MASTER",
        sourceLabel: `OEM Acquisition (₹${(Number(veh.purchase_cost || veh.purchase_price || 0)).toLocaleString()})`,
        isDirectVaultDoc: false
      });
    }

    return docs;
  }, []);

  // Vehicle Dossier Computed Statistics and Subsystem Entities
  const dossierData = useMemo(() => {
    if (!viewingVehicle) {
      return {
        services: [] as MaintenanceRecord[],
        parts: [] as PartAccessoryRecord[],
        trips: [] as TripRecord[],
        docs: [] as AggregatedVehicleDoc[],
        totalServiceSpend: 0,
        lastService: null as MaintenanceRecord | null,
        totalPartsValue: 0,
        activeWarrantiesCount: 0,
        expiredDocsCount: 0,
        completedTripsCount: 0,
        activeTripsCount: 0,
        hasPuc: false,
        hasInsurance: false,
        hasRc: false,
        hasFitness: false,
        hasPermit: false
      };
    }

    const normReg = (reg?: string | null) => (reg || "").replace(/[^a-zA-Z0-9]/g, "").toUpperCase();
    const targetId = viewingVehicle.id;
    const targetPlate = normReg(viewingVehicle.registration_number);

    // 1. Service / Maintenance Records
    const vServices = maintenance.filter(
      (m) =>
        (m.vehicle_id && m.vehicle_id === targetId) ||
        (m.vehicle_reg && normReg(m.vehicle_reg) === targetPlate)
    ).sort((a, b) => new Date(b.service_date).getTime() - new Date(a.service_date).getTime());

    const totalServiceSpend = vServices.reduce((sum, s) => sum + (Number(s.cost) || 0), 0);
    const lastService = vServices[0] || null;

    // 2. Mounted Spare Parts & Accessories
    const vParts = parts.filter(
      (p) =>
        (p.vehicle_id && p.vehicle_id === targetId) ||
        (p.assigned_vehicle_reg && normReg(p.assigned_vehicle_reg) === targetPlate)
    );

    const totalPartsValue = vParts.reduce((sum, p) => sum + (Number(p.purchase_amount) || 0), 0);
    const activeWarrantiesCount = vParts.filter((p) => {
      if (!p.warranty_expiry_date) return false;
      const days = calculateDaysRemaining(p.warranty_expiry_date);
      return days !== null && days >= 0;
    }).length;

    // 3. Trips Log
    const vTrips = trips.filter(
      (t) =>
        (t.vehicle_id && t.vehicle_id === targetId) ||
        (t.vehicle_reg && normReg(t.vehicle_reg) === targetPlate)
    ).sort((a, b) => new Date(b.plan_date || b.created_at || "").getTime() - new Date(a.plan_date || a.created_at || "").getTime());

    const completedTripsCount = vTrips.filter((t) => t.status === "COMPLETED").length;
    const activeTripsCount = vTrips.filter((t) => t.status === "ON_ROUTE" || t.status === "SCHEDULED").length;

    // 4. Unified 360° All-Module Vehicle Documents & Compliance Aggregation
    const allAggregatedDocs = computeVehicleAggregatedDocs(
      viewingVehicle,
      maintenance,
      parts,
      trips,
      drivers,
      viewingVehiclePolicies,
      viewingVehiclePucs
    );

    const expiredDocsCount = allAggregatedDocs.filter((d) => {
      if (!d.expiry_date) return false;
      const days = calculateDaysRemaining(d.expiry_date);
      return days !== null && days < 0;
    }).length;

    const hasPuc = Boolean(allAggregatedDocs.some((d) => d.doc_type === "PUC") || viewingVehicle.puc_certificate_number);
    const hasInsurance = Boolean(allAggregatedDocs.some((d) => d.doc_type === "INSURANCE") || viewingVehicle.insurance_policy_number);
    const hasRc = Boolean(allAggregatedDocs.some((d) => d.doc_type === "RC") || viewingVehicle.vin_chassis_number);
    const hasFitness = Boolean(allAggregatedDocs.some((d) => d.doc_type === "FITNESS") || viewingVehicle.fitness_expiry_date);
    const hasPermit = Boolean(allAggregatedDocs.some((d) => d.doc_type === "PERMIT"));

    return {
      services: vServices,
      parts: vParts,
      trips: vTrips,
      docs: allAggregatedDocs,
      totalServiceSpend,
      lastService,
      totalPartsValue,
      activeWarrantiesCount,
      expiredDocsCount,
      completedTripsCount,
      activeTripsCount,
      hasPuc,
      hasInsurance,
      hasRc,
      hasFitness,
      hasPermit
    };
  }, [viewingVehicle, maintenance, parts, trips, drivers, viewingVehiclePolicies, viewingVehiclePucs, computeVehicleAggregatedDocs]);

  const uploadVehicleDocumentViaRestOrAction = async (
    vehicleId: string,
    doc: {
      doc_type: string;
      title?: string;
      document_number?: string | null;
      expiry_date?: string | null;
      file_name: string;
      file_size?: string | null;
      file_type?: string | null;
      file_url: string;
      status?: string | null;
    }
  ): Promise<{ success: boolean; document?: VehicleDocumentRecord; error?: string }> => {
    try {
      const response = await fetch("/api/vehicle/documents/upload", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ vehicleId, doc })
      });
      if (response.ok) {
        return await response.json();
      }
    } catch (restErr) {
      console.warn("[FleetDeskHost] REST document upload failed, attempting action fallback:", restErr);
    }
    return await createVehicleDocumentAction(vehicleId, doc);
  };

  const deleteVehicleDocumentViaRestOrAction = async (documentId: string): Promise<{ success: boolean; error?: string }> => {
    try {
      const response = await fetch("/api/vehicle/documents/delete", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ documentId })
      });
      if (response.ok) {
        return await response.json();
      }
    } catch (restErr) {
      console.warn("[FleetDeskHost] REST document delete failed, attempting action fallback:", restErr);
    }
    return await deleteVehicleDocumentAction(documentId);
  };

  const executeDirectDocUpload = async (params: {
    file: File;
    base64Url: string;
    docType: string;
    title: string;
    documentNumber?: string | null;
    expiryDate?: string | null;
    replaceDocId?: string;
  }) => {
    if (!viewingVehicle) return;
    setDossierUploadingDoc(true);

    try {
      if (params.replaceDocId) {
        await deleteVehicleDocumentViaRestOrAction(params.replaceDocId);
      }

      const res = await uploadVehicleDocumentViaRestOrAction(viewingVehicle.id, {
        doc_type: params.docType,
        title: params.title,
        document_number: params.documentNumber || null,
        expiry_date: params.expiryDate || null,
        file_name: params.file.name,
        file_size: formatFileSize(params.file.size),
        file_type: params.file.type || resolveMimeFromName(params.file.name),
        file_url: params.base64Url,
        status: "VALID"
      });

      if (res.success && res.document) {
        setViewingVehicle((prev) => {
          if (!prev) return null;
          let updatedDocs = prev.documents || [];
          if (params.replaceDocId) {
            updatedDocs = updatedDocs.filter((d) => d.id !== params.replaceDocId);
          }
          return { ...prev, documents: [res.document!, ...updatedDocs] };
        });
        setVehicles((prev) =>
          prev.map((v) => {
            if (v.id !== viewingVehicle.id) return v;
            let updatedDocs = v.documents || [];
            if (params.replaceDocId) {
              updatedDocs = updatedDocs.filter((d) => d.id !== params.replaceDocId);
            }
            return { ...v, documents: [res.document!, ...updatedDocs] };
          })
        );
        triggerToast("Document successfully archived into vehicle vault.");
        setDossierNewDocTitle("");
        setDossierNewDocNumber("");
        setDossierNewDocExpiry("");
        setIsDossierAddDocOpen(false);
      } else {
        triggerToast(res.error || `Failed to save ${params.file.name} to vehicle vault.`, true);
      }
    } catch (err: any) {
      triggerToast(err.message || `Error saving ${params.file.name}`, true);
    } finally {
      setDossierUploadingDoc(false);
      const fileInput = document.getElementById("dossier-direct-doc-file-input") as HTMLInputElement;
      if (fileInput) fileInput.value = "";
    }
  };

  const handleDossierDirectDocUpload = async (fileList: FileList | File[]) => {
    if (!viewingVehicle) return;
    const files = Array.from(fileList);
    if (!files.length) return;

    const MAX_FILE_SIZE = 25 * 1024 * 1024;
    const BLOCKED_EXTS = ["exe", "bat", "cmd", "sh", "vbs", "js", "scr", "msi", "dll"];

    const validFiles = files.filter((f) => {
      const ext = f.name.split(".").pop()?.toLowerCase() || "";
      if (BLOCKED_EXTS.includes(ext)) {
        triggerToast(`Executable/script files (.${ext}) are not permitted.`, true);
        return false;
      }
      if (f.size > MAX_FILE_SIZE) {
        triggerToast(`File "${f.name}" exceeds maximum allowed size (25MB).`, true);
        return false;
      }
      return true;
    });

    if (!validFiles.length) return;

    const file = validFiles[0];

    // Smart semantic detection of document type from filename or user title
    let targetDocType = dossierNewDocType;
    const lowerFileName = file.name.toLowerCase();
    const lowerTitle = (dossierNewDocTitle || "").toLowerCase();

    if (
      lowerFileName.includes("rc") ||
      lowerFileName.includes("smartcard") ||
      lowerFileName.includes("registration") ||
      lowerTitle.includes("rc ") ||
      lowerTitle.includes("smart card") ||
      lowerTitle.includes("registration certificate")
    ) {
      targetDocType = "RC";
    } else if (
      lowerFileName.includes("insur") ||
      lowerFileName.includes("policy") ||
      lowerTitle.includes("insur") ||
      lowerTitle.includes("policy")
    ) {
      targetDocType = "INSURANCE";
    } else if (
      lowerFileName.includes("puc") ||
      lowerFileName.includes("pollution") ||
      lowerFileName.includes("emission") ||
      lowerTitle.includes("puc") ||
      lowerTitle.includes("pollution")
    ) {
      targetDocType = "PUC";
    } else if (lowerFileName.includes("fitness") || lowerTitle.includes("fitness")) {
      targetDocType = "FITNESS";
    } else if (lowerFileName.includes("permit") || lowerTitle.includes("permit")) {
      targetDocType = "PERMIT";
    } else if (lowerFileName.includes("tax") || lowerTitle.includes("tax")) {
      targetDocType = "ROAD_TAX";
    }

    const typeOption = VEHICLE_DOC_TYPES.find((t) => t.value === targetDocType);
    const resolvedTitle = dossierNewDocTitle.trim() || `${typeOption?.label || "Vehicle Document"} (${viewingVehicle.registration_number})`;
    const docNumber = dossierNewDocNumber.trim() || null;
    const expiryDate = dossierNewDocExpiry || null;

    let base64Url = "";
    try {
      base64Url = await new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = (e) => resolve((e.target?.result as string) || "");
        reader.onerror = (e) => reject(e);
        reader.readAsDataURL(file);
      });
    } catch (err: any) {
      triggerToast(err.message || `Error reading ${file.name}`, true);
      return;
    }

    if (!base64Url) {
      triggerToast(`Failed to read file: ${file.name}`, true);
      return;
    }

    // Comprehensive duplicate detection against existing vehicle vault docs & master compliance records
    const allExistingDocs = (dossierData?.docs || []).length > 0
      ? dossierData.docs
      : (viewingVehicle.documents || []);

    const cleanBaseCandidate = resolvedTitle.replace(/\s*\(v?\d+(?:\.\d+)?\)\s*$/i, "").trim().toLowerCase();
    const targetVin = (viewingVehicle.vin_chassis_number || "").toLowerCase().trim();

    const matchedExisting = allExistingDocs.find((d: any) => {
      const existingBase = (d.title || "").replace(/\s*\(v?\d+(?:\.\d+)?\)\s*$/i, "").trim().toLowerCase();
      const sameTitle = existingBase && (existingBase === cleanBaseCandidate || existingBase.includes(cleanBaseCandidate) || cleanBaseCandidate.includes(existingBase));
      const sameFileName = d.file_name && d.file_name.toLowerCase().trim() === file.name.toLowerCase().trim();
      const sameDocNumber = docNumber && d.document_number && d.document_number.toLowerCase().trim() === docNumber.toLowerCase().trim();
      const isRcMatch = targetDocType === "RC" && (
        d.doc_type === "RC" ||
        existingBase.includes("rc smart card") ||
        (targetVin && (d.document_number || "").toLowerCase().trim() === targetVin)
      );
      const isStatutoryMatch = (targetDocType === "INSURANCE" || targetDocType === "PUC" || targetDocType === "FITNESS") && d.doc_type === targetDocType;

      return sameDocNumber || sameFileName || (sameTitle && (sameDocNumber || d.file_url)) || isRcMatch || isStatutoryMatch;
    });

    if (matchedExisting) {
      const versionInfo = computeNextDocVersion(
        matchedExisting.title || resolvedTitle,
        allExistingDocs.filter((d: any) => d.doc_type === targetDocType),
        targetDocType
      );

      setDuplicateDocPrompt({
        file,
        base64Url,
        docType: targetDocType,
        docTitle: resolvedTitle,
        documentNumber: docNumber || (matchedExisting as any).document_number || null,
        expiryDate: expiryDate || (matchedExisting as any).expiry_date || null,
        existingDoc: matchedExisting,
        currentVersion: versionInfo.currentVersion,
        nextVersion: versionInfo.nextVersion,
        baseTitle: versionInfo.baseTitle
      });
      return;
    }

    // No duplicate detected -> execute normal upload
    await executeDirectDocUpload({
      file,
      base64Url,
      docType: targetDocType,
      title: resolvedTitle,
      documentNumber: docNumber,
      expiryDate
    });
  };

  const handleConfirmVersionUpload = async () => {
    if (!duplicateDocPrompt) return;
    const { file, base64Url, docType, baseTitle, nextVersion, documentNumber, expiryDate } = duplicateDocPrompt;
    const versionedTitle = `${baseTitle} (${nextVersion})`;

    setDuplicateDocPrompt(null);
    await executeDirectDocUpload({
      file,
      base64Url,
      docType,
      title: versionedTitle,
      documentNumber,
      expiryDate
    });
    triggerToast(`Document uploaded successfully as Version ${nextVersion}`);
  };

  const handleConfirmReplaceUpload = async () => {
    if (!duplicateDocPrompt) return;
    const { file, base64Url, docType, docTitle, documentNumber, expiryDate, existingDoc } = duplicateDocPrompt;

    const replaceId = existingDoc?.id && !existingDoc.id.startsWith("master-") ? existingDoc.id : undefined;

    setDuplicateDocPrompt(null);
    await executeDirectDocUpload({
      file,
      base64Url,
      docType,
      title: docTitle,
      documentNumber,
      expiryDate,
      replaceDocId: replaceId
    });
    triggerToast("Existing document replaced successfully with new scan.");
  };

  const handleCancelDuplicateUpload = () => {
    setDuplicateDocPrompt(null);
    const fileInput = document.getElementById("dossier-direct-doc-file-input") as HTMLInputElement;
    if (fileInput) fileInput.value = "";
  };

  const handleUniversalDeleteDocument = async (doc: AggregatedVehicleDoc) => {
    if (!viewingVehicle) return;
    const isVaultDoc = doc.isDirectVaultDoc || doc.id.startsWith("vdoc-");
    const confirmMsg = `Are you sure you want to permanently delete "${doc.title || doc.file_name}" from the vehicle vault?`;
    if (!confirm(confirmMsg)) return;

    setDossierUploadingDoc(true);
    try {
      if (isVaultDoc) {
        const res = await deleteVehicleDocumentViaRestOrAction(doc.id);
        if (res.success) {
          setViewingVehicle((prev) => {
            if (!prev) return null;
            return { ...prev, documents: (prev.documents || []).filter((d) => d.id !== doc.id) };
          });
          setVehicles((prev) =>
            prev.map((v) =>
              v.id === viewingVehicle.id
                ? { ...v, documents: (v.documents || []).filter((d) => d.id !== doc.id) }
                : v
            )
          );
          triggerToast("Document deleted successfully from vehicle vault.");
        } else {
          triggerToast(res.error || "Failed to delete document.", true);
        }
      } else if (doc.id.startsWith("master-doc-")) {
        const updates: any = {};
        if (doc.doc_type === "RC") updates.rc_doc_url = null;
        else if (doc.doc_type === "INSURANCE") updates.insurance_doc_url = null;
        else if (doc.doc_type === "PUC") updates.puc_doc_url = null;
        else if (doc.doc_type === "FITNESS") updates.fitness_doc_url = null;
        else if (doc.doc_type === "PERMIT") updates.permit_doc_url = null;
        else if (doc.doc_type === "ROAD_TAX") updates.road_tax_doc_url = null;
        else if (doc.doc_type === "INVOICE") updates.invoice_doc_url = null;

        const res = await updateVehicleAction(viewingVehicle.id, updates);
        if (res.success) {
          setViewingVehicle((prev) => prev ? { ...prev, ...updates } : null);
          setVehicles((prev) => prev.map((v) => v.id === viewingVehicle.id ? { ...v, ...updates } : v));
          triggerToast("Document removed successfully.");
        } else {
          triggerToast(res.error || "Failed to remove document.", true);
        }
      } else if (doc.id.startsWith("ins-pol-")) {
        const polId = doc.id.replace("ins-pol-", "");
        const res = await deleteVehicleInsurancePolicyAction(polId, viewingVehicle.id);
        if (res.success) {
          triggerToast("Insurance policy document deleted.");
          loadAllData(true);
        } else {
          triggerToast(res.error || "Failed to delete policy.", true);
        }
      } else if (doc.id.startsWith("puc-test-")) {
        const pucId = doc.id.replace("puc-test-", "");
        const res = await deleteVehiclePucCertificateAction(pucId, viewingVehicle.id);
        if (res.success) {
          triggerToast("PUC certificate document deleted.");
          loadAllData(true);
        } else {
          triggerToast(res.error || "Failed to delete certificate.", true);
        }
      } else {
        setViewingVehicle((prev) => {
          if (!prev) return null;
          return { ...prev, documents: (prev.documents || []).filter((d) => d.id !== doc.id) };
        });
        triggerToast("Document removed.");
      }
    } catch (err: any) {
      triggerToast(err.message || "Failed to delete document.", true);
    } finally {
      setDossierUploadingDoc(false);
    }
  };

  const handleInlineViewerDocUpload = async (file: File) => {
    if (!file) return;
    const MAX_FILE_SIZE = 25 * 1024 * 1024;
    const BLOCKED_EXTS = ["exe", "bat", "cmd", "sh", "vbs", "js", "scr", "msi", "dll"];
    const ext = file.name.split(".").pop()?.toLowerCase() || "";
    if (BLOCKED_EXTS.includes(ext)) {
      triggerToast(`Executable/script files (.${ext}) are not permitted.`, true);
      return;
    }
    if (file.size > MAX_FILE_SIZE) {
      triggerToast(`File "${file.name}" exceeds maximum allowed size (25MB).`, true);
      return;
    }

    try {
      const base64Url = await new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = (e) => resolve((e.target?.result as string) || "");
        reader.onerror = (e) => reject(e);
        reader.readAsDataURL(file);
      });

      if (!base64Url) {
        triggerToast("Failed to read file", true);
        return;
      }

      if (viewingVehicle && previewAttachment) {
        const docType = (previewAttachment as any).doc_type || "OTHER";
        const docTitle = (previewAttachment as any).title || file.name;
        const res = await uploadVehicleDocumentViaRestOrAction(viewingVehicle.id, {
          doc_type: docType,
          title: docTitle,
          document_number: (previewAttachment as any).document_number || null,
          expiry_date: (previewAttachment as any).expiry_date || null,
          file_name: file.name,
          file_size: formatFileSize(file.size),
          file_type: file.type || resolveMimeFromName(file.name),
          file_url: base64Url,
          status: "VALID"
        });

        if (res.success && res.document) {
          setViewingVehicle((prev) => {
            if (!prev) return null;
            return { ...prev, documents: [res.document!, ...(prev.documents || [])] };
          });
          setVehicles((prev) =>
            prev.map((v) =>
              v.id === viewingVehicle.id
                ? { ...v, documents: [res.document!, ...(v.documents || [])] }
                : v
            )
          );
        }
      }

      if (previewAttachment) {
        setPreviewAttachment({
          ...previewAttachment,
          file_name: file.name,
          file_size: formatFileSize(file.size),
          file_type: file.type || resolveMimeFromName(file.name),
          file_url: base64Url
        });
      }
      triggerToast("Physical scan attached and loaded into document viewer successfully!");
    } catch (err: any) {
      triggerToast(err.message || "Error reading file", true);
    }
  };

  const handleCreateVehicle = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    const rawPlate = newVehiclePlate.trim().toUpperCase();
    if (!rawPlate) {
      triggerToast("Please enter a vehicle registration number.", true);
      return;
    }

    if (editVehicleRegDate && editVehicleInsuranceExpiry && editVehicleInsuranceExpiry < editVehicleRegDate) {
      triggerToast("Insurance Expiry Date cannot be earlier than Vehicle Registration Date.", true);
      return;
    }
    if (editVehicleRegDate && editVehiclePucExpiry && editVehiclePucExpiry < editVehicleRegDate) {
      triggerToast("PUC Expiry Date cannot be earlier than Vehicle Registration Date.", true);
      return;
    }
    if (editVehicleRegDate && editVehicleFitnessExpiry && editVehicleFitnessExpiry < editVehicleRegDate) {
      triggerToast("Fitness Expiry Date cannot be earlier than Vehicle Registration Date.", true);
      return;
    }
    if (editVehicleRegDate && editVehicleCustomExtendedExpiryDate && editVehicleCustomExtendedExpiryDate <= editVehicleRegDate) {
      triggerToast("Custom Extended Expiry Date must be after Registration Date.", true);
      return;
    }

    setModalSubmitting(true);
    try {
      let make = newVehicleMake.trim();
      let model = newVehicleModel.trim();
      let variant = newVehicleVariant.trim();
      let category = newVehicleCategory;
      let fuel = newVehicleFuel;
      let vin = newVehicleVin.trim();
      let engine = newVehicleEngine.trim();
      let rto = newVehicleRtoOffice.trim();
      let owner = newVehicleOwner.trim();
      let rtoRmn = newVehicleRtoRmn.trim();
      let regDate = newVehicleRegDate;
      let insVendorId = newVehicleInsuranceVendorId;
      let insVendor = newVehicleInsuranceVendor.trim();
      let insPolicy = newVehicleInsurancePolicy.trim();
      let insExp = newVehicleInsuranceExpiry;
      let pucExp = newVehiclePucExpiry;
      let fitExp = newVehicleFitnessExpiry;
      let odo = Number(newVehicleOdometer) || 0;
      let nickname = (newVehicleNickname.trim() || `${make} ${model}`).trim();

      const isElectric = isElectricFuel(fuel);

      // Mandatory validation for required input fields
      if (!rawPlate) {
        triggerToast("Registration plate number (Regn. No.) is mandatory.", true);
        setModalSubmitting(false);
        return;
      }
      if (!make || !model) {
        triggerToast("Vehicle Name (Make & Model) is mandatory.", true);
        setModalSubmitting(false);
        return;
      }
      if (!owner) {
        triggerToast("Owner Name (Registered Owner) is mandatory.", true);
        setModalSubmitting(false);
        return;
      }
      if (!isElectric && !pucExp) {
        triggerToast("PUC End Date is mandatory for non-electric vehicles.", true);
        setModalSubmitting(false);
        return;
      }
      if (!insExp) {
        triggerToast("Insurance End Date is mandatory.", true);
        setModalSubmitting(false);
        return;
      }
      if (!regDate) {
        triggerToast("Registration Date is mandatory.", true);
        setModalSubmitting(false);
        return;
      }
      if (insExp && regDate && insExp < regDate) {
        triggerToast("Insurance Expiry Date cannot be earlier than Vehicle Registration Date.", true);
        setModalSubmitting(false);
        return;
      }
      if (!isElectric && pucExp && regDate && pucExp < regDate) {
        triggerToast("PUC Expiry Date cannot be earlier than Vehicle Registration Date.", true);
        setModalSubmitting(false);
        return;
      }
      if (fitExp && regDate && fitExp < regDate) {
        triggerToast("Fitness Expiry Date cannot be earlier than Vehicle Registration Date.", true);
        setModalSubmitting(false);
        return;
      }
      if (!vin) {
        triggerToast("Chassis Number (VIN) is mandatory.", true);
        setModalSubmitting(false);
        return;
      }
      if (!engine) {
        triggerToast("Engine Number is mandatory.", true);
        setModalSubmitting(false);
        return;
      }
      if (!rtoRmn) {
        triggerToast("RTO RMN (Registered Mobile Number) is mandatory.", true);
        setModalSubmitting(false);
        return;
      }

      const res = await submitNewVehicle({
        registration_number: rawPlate,
        make: make.trim(),
        model: model.trim(),
        variant: variant || "Standard",
        category,
        status: newVehicleStatus,
        odometer_km: odo,
        assigned_driver_id: newVehicleDriverId || undefined,
        nickname: nickname,
        paint_color: newVehicleColor || undefined,
        vin_chassis_number: vin,
        engine_number: engine,
        fuel_type: fuel,
        registration_date: regDate,
        rto_office: rto || undefined,
        registered_owner: owner,
        rto_rmn: rtoRmn,
        insurance_vendor_id: insVendorId || undefined,
        insurance_vendor: insVendor || undefined,
        insurance_policy_number: insPolicy || undefined,
        insurance_expiry_date: insExp,
        puc_expiry_date: isElectric ? undefined : pucExp,
        fitness_expiry_date: fitExp || undefined,
        has_roadside_assistance: newVehicleRsa,
        has_hsrp_plate: newVehicleHsrp,
        basic_price: Number(newVehicleBasicPrice) || 0,
        gst_percentage: Number(newVehicleGstPercent) || 0,
        gst_amount: Number(newVehicleGstAmount) || 0,
        cess_percentage: Number(newVehicleCessPercent) || 0,
        cess_amount: Number(newVehicleCessAmount) || 0,
        ex_showroom_price: Number(newVehicleExShowroomPrice) || 0,
        rto_road_tax: Number(newVehicleRtoRoadTax) || 0,
        tcs_amount: Number(newVehicleTcsAmount) || 0,
        insurance_cost: Number(newVehicleInsuranceCost) || 0,
        hsrp_smart_card_fee: Number(newVehicleHsrpFee) || 0,
        fastag_charges: Number(newVehicleFastagCharges) || 0,
        accessories_cost: Number(newVehicleAccessoriesCost) || 0,
        extended_warranty_cost: Number(newVehicleExtendedWarrantyCost) || 0,
        other_charges: Number(newVehicleOtherCharges) || 0,
        discount_amount: Number(newVehicleDiscountAmount) || 0,
        on_road_price: Number(newVehicleOnRoadPrice) || Number(newVehiclePurchasePrice) || 0,
        purchase_price: Number(newVehicleOnRoadPrice) || Number(newVehiclePurchasePrice) || 0,
        purchase_cost: Number(newVehicleOnRoadPrice) || Number(newVehiclePurchasePrice) || 0,
        custom_extended_expiry_date: newVehicleCustomExtendedExpiryDate ? newVehicleCustomExtendedExpiryDate : undefined,
        documents: newVehicleDocs
      });

      if (res.success) {
        triggerToast(`Vehicle ${newVehiclePlate.toUpperCase()} registered successfully!`);
        handleResetVehicleForm();
        loadAllData(true);
        router.push("/vehicle/inventory");
      } else {
        triggerToast(res.error || "Failed to add vehicle", true);
      }
    } catch (err: any) {
      triggerToast(err.message || "Failed to add vehicle", true);
    } finally {
      setModalSubmitting(false);
    }
  };

  const openEditVehicleModal = (veh: VehicleRecord) => {
    setSelectedVehicleForEdit(veh);
    setEditPortalLookupMsg(null);
    setEditVehiclePlate(veh.registration_number);
    setEditVehicleMake(veh.make);
    setEditVehicleModel(veh.model);
    setEditVehicleVariant(veh.variant || "");
    setEditVehicleCategory(veh.category || "CAR");
    setEditVehicleStatus(veh.status || "IN_STOCK");
    setEditVehicleOdometer(veh.odometer_km || 0);
    setEditVehicleDriverId(veh.assignedDriver?.id || "");
    setEditVehicleNickname(veh.nickname || "");
    setEditVehicleColor(veh.paint_color || "#1e293b");
    setEditVehicleVin(veh.vin_chassis_number || "");
    setEditVehicleEngine(veh.engine_number || "");
    setEditVehicleFuel(veh.fuel_type || "Petrol");
    setEditVehicleRegDate(normalizeDateToInputFormat(veh.registration_date));
    setEditVehicleRtoOffice(veh.rto_office || "");
    setEditVehicleOwner(veh.registered_owner || "");
    setEditVehicleRtoRmn(veh.rto_rmn || "");
    setEditVehicleInsuranceVendorId(veh.insurance_vendor_id || "");
    setEditVehicleInsuranceVendor(veh.insurance_vendor || "");
    setEditVehicleInsurancePolicy(veh.insurance_policy_number || "");
    const isEv = isElectricFuel(veh.fuel_type);
    setEditVehicleInsuranceExpiry(normalizeDateToInputFormat(veh.insurance_expiry_date));
    setEditVehiclePucExpiry(isEv ? "" : normalizeDateToInputFormat(veh.puc_expiry_date));
    setEditVehicleFitnessExpiry(normalizeDateToInputFormat(veh.fitness_expiry_date));
    setEditVehicleHsrp(veh.has_hsrp_plate !== undefined ? veh.has_hsrp_plate : true);
    setEditVehicleRsa(veh.has_roadside_assistance !== undefined ? veh.has_roadside_assistance : true);
    
    // Pricing Breakdown States for Edit Modal
    const toCleanPrice = (val: any) => {
      if (val === null || val === undefined || val === "" || Number(val) === 0) return "";
      return val;
    };
    setEditVehicleBasicPrice(toCleanPrice(veh.basic_price));
    setEditVehicleGstPercent(veh.gst_percentage !== undefined && veh.gst_percentage !== null ? veh.gst_percentage : 28);
    setEditVehicleGstAmount(toCleanPrice(veh.gst_amount));
    setEditVehicleCessPercent(veh.cess_percentage !== undefined && veh.cess_percentage !== null ? veh.cess_percentage : 0);
    setEditVehicleCessAmount(toCleanPrice(veh.cess_amount));
    setEditVehicleExShowroomPrice(toCleanPrice(veh.ex_showroom_price || veh.purchase_price || veh.purchase_cost));
    setEditVehicleRtoRoadTax(toCleanPrice(veh.rto_road_tax));
    setEditVehicleTcsAmount(toCleanPrice(veh.tcs_amount));
    setEditVehicleInsuranceCost(toCleanPrice(veh.insurance_cost));
    setEditVehicleHsrpFee(toCleanPrice(veh.hsrp_smart_card_fee));
    setEditVehicleFastagCharges(toCleanPrice(veh.fastag_charges));
    setEditVehicleAccessoriesCost(toCleanPrice(veh.accessories_cost));
    setEditVehicleExtendedWarrantyCost(toCleanPrice(veh.extended_warranty_cost));
    setEditVehicleOtherCharges(toCleanPrice(veh.other_charges));
    setEditVehicleDiscountAmount(toCleanPrice(veh.discount_amount));
    setEditVehicleOnRoadPrice(toCleanPrice(veh.on_road_price || veh.purchase_price || veh.purchase_cost));
    setEditVehiclePurchasePrice(toCleanPrice(veh.on_road_price || veh.purchase_price || veh.purchase_cost));
    setEditVehicleCustomExtendedExpiryDate(normalizeDateToInputFormat(veh.custom_extended_expiry_date));
    setEditVehicleDocs(veh.documents || []);
    setEditDocTitle("");
    setEditDocNumber("");
    setEditDocExpiry("");
    fetchVehicleDocumentsAction(veh.id).then((res) => {
      if (res.success && res.documents) {
        setEditVehicleDocs(res.documents);
      }
    }).catch((err) => console.error("Error fetching vehicle edit docs:", err));
    setEditVehicleSectionTab("SPECS");
    setIsEditVehicleOpen(true);
  };

  const handleEditPortalAutoFetch = async (plateOverride?: string) => {
    const rawPlate = (plateOverride || editVehiclePlate).trim();
    if (!rawPlate) {
      setEditPortalLookupMsg({
        type: "error",
        message: "Please enter a vehicle registration number first."
      });
      return;
    }

    setFetchingEditPortal(true);
    setEditPortalLookupMsg(null);

    try {
      const res = await queryVehiclePortal(rawPlate, editVehicleCategory);
      if (res.success && res.data) {
        const d = res.data;
        if (d.registration_number) setEditVehiclePlate(d.registration_number);
        if (d.make) setEditVehicleMake(d.make);
        if (d.model) setEditVehicleModel(d.model);
        if (d.variant) setEditVehicleVariant(d.variant);
        if (d.category) setEditVehicleCategory(d.category);
        if (d.nickname) setEditVehicleNickname(d.nickname);
        if (d.paint_color) setEditVehicleColor(d.paint_color);
        if (d.vin_chassis_number) setEditVehicleVin(d.vin_chassis_number);
        if (d.engine_number) setEditVehicleEngine(d.engine_number);
        if (d.fuel_type) setEditVehicleFuel(d.fuel_type);
        if (d.registration_date) setEditVehicleRegDate(normalizeDateToInputFormat(d.registration_date));
        if (d.rto_office) setEditVehicleRtoOffice(d.rto_office);
        if (d.registered_owner) setEditVehicleOwner(d.registered_owner);
        if (d.rto_rmn) setEditVehicleRtoRmn(d.rto_rmn);
        if (d.insurance_policy_number) setEditVehicleInsurancePolicy(d.insurance_policy_number);
        if (d.insurance_expiry_date) setEditVehicleInsuranceExpiry(normalizeDateToInputFormat(d.insurance_expiry_date));
        if (isElectricFuel(d.fuel_type)) {
          setEditVehiclePucExpiry("");
        } else if (d.puc_expiry_date) {
          setEditVehiclePucExpiry(normalizeDateToInputFormat(d.puc_expiry_date));
        }
        if (d.fitness_expiry_date) setEditVehicleFitnessExpiry(normalizeDateToInputFormat(d.fitness_expiry_date));

        const rtoLocation = d.rto_office || "RTO Registry Office";

        setEditPortalLookupMsg({
          type: "success",
          message: `All details updated: ${d.make} ${d.model}${d.variant ? ` (${d.variant})` : ""} • ${rtoLocation}`,
          rtoOffice: d.rto_office,
          source: d.source || "Universal RTO Portal"
        });
      } else {
        setEditPortalLookupMsg({
          type: "error",
          message: res.error || "Could not fetch vehicle specifications from portal."
        });
      }
    } catch (err: any) {
      const isSkew = err?.message?.includes("was not found on the server") || err?.message?.includes("failed-to-find-server-action");
      setEditPortalLookupMsg({
        type: "error",
        message: isSkew
          ? "Portal update detected. Please refresh your browser tab (Ctrl+R) to synchronize."
          : (err.message || "Failed to connect to vehicle portal service.")
      });
    } finally {
      setFetchingEditPortal(false);
    }
  };

