    isEditDriverOpen,
    isDispatchTripOpen,
    isAddMaintenanceOpen,
    isEditMaintenanceOpen,
    isVendorModalOpen,
    isAddPartOpen,
    isEditPartOpen,
    isRenewPartOpen,
    isRenewPolicyModalOpen,
    isPolicyHistoryModalOpen,
